72	export function codeWorkRunner({ root, repo, defaultBranch, env = process.env }) {
73	  return async function runFor(task, { item, context = [] }) {
74	    const missing = missingSecrets(task.decl.required_secrets ?? [], env);
75	    if (missing.length) return { ok: true, agentRequested: false, missingSecrets: missing };
76	
77	    const requestPath = agentRequestPath({ pack: task.pack, task: task.id, slotId: `item-${item.number}` });
78	    clearAgentRequest(requestPath);
