82	      taskDir: task.taskDir,
83	      env: { ...taskEnv(task.decl.required_secrets ?? [], env), ...codeWorkEnv({ root, repo, defaultBranch, task, item, context, requestPath }) },
84	      timeoutSeconds: task.decl.code_work_timeout,
85	    });
86	    console.log('::endgroup::');
